// 定义一个简单的柯里化函数，用于计算折扣后的价格
// 基础版：接受折扣率和原价，返回最终价格
function discount(rate: number): (price: number) => number {
  // 内部函数形成闭包，捕获 rate 变量
  return (price: number) => {
    return price * (1 - rate);
  };
}

// 创建特定折扣率的函数
const tenPercentOff = discount(0.1);   // 九折
const twentyPercentOff = discount(0.2); // 八折

console.log(tenPercentOff(100));    // 90
console.log(twentyPercentOff(100)); // 80

// 更通用的柯里化：支持任意数量的参数
// 使用函数重载描述类型
function curry<T extends any[], R>(fn: (...args: T) => R): CurriedArgs<T, R>;

// 工具类型：递归地将参数列表转换为嵌套函数
type CurriedArgs<T extends any[], R> =
  T extends [infer First, ...infer Rest]
    ? (arg: First) => CurriedArgs<Rest, R>
    : R;

// 实现（这里简化为固定长度，实际应用需处理变长）
function curry<T extends any[], R>(fn: (...args: T) => R): any {
  return function curried(...args: any[]) {
    if (args.length >= fn.length) {
      return fn(...args);
    } else {
      return (...nextArgs: any[]) => curried(...args, ...nextArgs);
    }
  };
}

// 使用例子：一个求和函数
function add(a: number, b: number, c: number) {
  return a + b + c;
}

const curriedAdd = curry(add);
console.log(curriedAdd(1)(2)(3)); // 6
console.log(curriedAdd(1, 2)(3)); // 6

